1	package com.example.starter.rolling.service;
2	
3	import com.example.starter.rolling.api.dto.RollActualRequest;
4	import com.example.starter.rolling.api.dto.RollActualView;
5	import com.example.starter.rolling.api.dto.RollFreezeRequest;
6	import com.example.starter.rolling.api.dto.RollMountRequest;
7	import com.example.starter.rolling.api.dto.RollView;
8	import com.example.starter.rolling.repo.IdAllocator;
9	import com.example.starter.rolling.repo.RollLifeRepository;
10	import com.example.starter.rolling.repo.RollLifeRepository.IdempotentRow;
11	import com.example.starter.rolling.repo.RollLifeRepository.RollActualRow;
12	import com.example.starter.rolling.repo.RollLifeRepository.RollRow;
13	import org.springframework.http.HttpStatus;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	
17	import java.math.BigDecimal;
18	import java.time.Clock;
19	import java.time.LocalDateTime;
20	import java.util.List;
21	
22	/**
23	 * 轧辊寿命台账领域服务：上机申请、换辊实绩回报、日冻结、台账复算。
24	 *
25	 * <p>核心规则：</p>
26	 * <ul>
27	 *   <li>实绩入库与累计里程更新在同一事务内完成；累计里程达到周期上限立即禁排，
28	 *       超限实绩整单回滚不得入库；</li>
29	 *   <li>新辊上机后前 5 卷按实绩时刻归位加首用标记，沿用既有烫辊规则；</li>
30	 *   <li>寿命到期轧辊申请上机直接拒绝并给出剩余里程；</li>
31	 *   <li>同一轧辊同时刻只允许一张实绩回报（唯一索引裁决），并发按 requestId 幂等：
32	 *       指纹覆盖 requestId 与全部业务字段，同键同参返回首次结果，同键异参 409；</li>
33	 *   <li>日冻结后迟到实绩只记迟到事件，不改已冻结里程；缺轧辊号的实绩直接拒绝，
34	 *       拒绝记录不增加里程。</li>
35	 * </ul>
36	 */
37	@Service
38	public class RollLifeService {
39	
40	    /** 新辊上机后沿用烫辊规则并加首用标记的卷数，恰第 5 卷为最后首用位。 */
41	    public static final int FIRST_USE_COILS = 5;
42	
43	    private static final String BIZ_MOUNT = "ROLL_MOUNT";
44	    private static final String BIZ_ACTUAL = "ROLL_ACTUAL";
45	    private static final String BIZ_FREEZE = "ROLL_FREEZE";
46	
47	    private static final String STATUS_IN_SERVICE = "IN_SERVICE";
48	    private static final String STATUS_BANNED = "BANNED";
49	
50	    private final RollLifeRepository repo;
51	    private final IdAllocator idAllocator;
52	    private final Clock clock;
53	
54	    public RollLifeService(RollLifeRepository repo, IdAllocator idAllocator, Clock clock) {
55	        this.repo = repo;
56	        this.idAllocator = idAllocator;
57	        this.clock = clock;
58	    }
59	
60	    // ---------------- 上机申请 ----------------
61	
62	    @Transactional
63	    public RollView mount(RollMountRequest request) {
64	        String fp = FingerprintUtil.fingerprint(request);
65	        Object replay = replayIfSame(request.requestId(), BIZ_MOUNT, fp);
66	        if (replay != null) {
67	            return (RollView) replay;
68	        }
69	
70	        LocalDateTime now = LocalDateTime.now(clock);
71	        RollRow roll = repo.findRoll(request.rollNo());
72	        if (roll != null) {
73	            BigDecimal remaining = roll.cycleLimitKm().subtract(roll.totalKm());
74	            if (roll.totalKm().compareTo(roll.cycleLimitKm()) >= 0) {
75	                // 寿命到期：直接拒绝并给出剩余里程，不产生任何台账写入。
76	                throw new BusinessException(HttpStatus.BAD_REQUEST,
77	                        "轧辊 " + request.rollNo() + " 寿命到期，禁止上机：累计里程 "
78	                                + roll.totalKm().stripTrailingZeros().toPlainString()
79	                                + " 公里已达周期上限 " + roll.cycleLimitKm().stripTrailingZeros().toPlainString()
80	                                + " 公里，剩余里程 " + remaining.stripTrailingZeros().toPlainString() + " 公里");
81	            }
82	            // 换辊重新上机：卷数归零，前 5 卷重新进入首用烫辊位；累计里程不清零。
83	            repo.remount(request.rollNo(), request.mountedAt(), now);
84	        } else {
85	            repo.insertRoll(new RollRow(request.rollNo(), STATUS_IN_SERVICE, BigDecimal.ZERO,
86	                    request.cycleLimitKm(), 0, request.mountedAt(), null, now, now));
87	        }
88	
89	        RollView view = buildView(repo.findRoll(request.rollNo()));
90	        saveIdempotent(request.requestId(), BIZ_MOUNT, fp, 200, FingerprintUtil.toJson(view));
91	        return view;
92	    }
93	
94	    // ---------------- 换辊实绩回报 ----------------
95	
96	    @Transactional
97	    public RollActualView reportActual(RollActualRequest request) {
98	        String fp = FingerprintUtil.fingerprint(request);
99	        Object replay = replayIfSame(request.requestId(), BIZ_ACTUAL, fp);
100	        if (replay != null) {
101	            return (RollActualView) replay;
102	        }
103	
104	        // 缺轧辊号直接拒绝并提示补录；拒绝记录不写库、不增加里程，允许补录后用同键重报。
105	        if (request.rollNo() == null || request.rollNo().isBlank()) {
106	            throw new BusinessException(HttpStatus.BAD_REQUEST,
107	                    "实绩缺少轧辊号，请补录轧辊号后重新回报；本次拒绝记录未增加任何里程");
108	        }
109	
110	        RollRow roll = repo.findRoll(request.rollNo());
111	        if (roll == null) {
112	            throw new BusinessException(HttpStatus.NOT_FOUND,
113	                    "轧辊 " + request.rollNo() + " 不存在，请先申请上机");
114	        }
115	
116	        // 按“轧辊号＋实绩时刻”去重：已存在的实绩按首次结果幂等返回。
117	        RollActualRow existing = repo.findActual(request.rollNo(), request.recordedAt());
118	        if (existing != null) {
119	            return dedupActualView(request.requestId(), fp, existing);
120	        }
121	
122	        LocalDateTime now = LocalDateTime.now(clock);
123	
124	        // 日冻结终态：迟到实绩只记迟到事件，不改已冻结里程与禁排结论。
125	        if (roll.frozenAt() != null) {
126	            long eventId = idAllocator.nextId();
127	            repo.insertLateEvent(eventId, request.rollNo(), request.requestId(),
128	                    request.rollingKm(), request.recordedAt(), now);
129	            RollActualView lateView = new RollActualView(request.rollNo(), null, false, true,
130	                    false, roll.totalKm(), remaining(roll), isBanned(roll), request.recordedAt());
131	            saveIdempotent(request.requestId(), BIZ_ACTUAL, fp, 200,
132	                    FingerprintUtil.toJson(lateView));
133	            return lateView;
134	        }
135	
136	        // 首用标记：按实绩时刻归位，本卷之前（含上机时刻起）已入库卷数小于 5 即首用烫辊位。
137	        boolean firstUse = repo.countCoilsSinceMountBefore(request.rollNo(), roll.mountedAt(),
138	                request.recordedAt()) < FIRST_USE_COILS;
139	
140	        long actualId = idAllocator.nextId();
141	        try {
142	            repo.insertActual(new RollActualRow(actualId, request.rollNo(), request.rollingKm(),
143	                    firstUse, request.recordedAt(), request.requestId(), fp, now));
144	        } catch (org.springframework.dao.DuplicateKeyException e) {
145	            // 并发同辊同时刻回报：唯一索引裁决后按首次实绩幂等返回。
146	            RollActualRow winner = repo.findActual(request.rollNo(), request.recordedAt());
147	            if (winner != null) {
148	                return dedupActualView(request.requestId(), fp, winner);
149	            }
150	            throw e;
151	        }
152	
153	        // 里程累计与实绩入库同事务：超限则整单回滚，超限实绩不得入库。
154	        boolean withinLimit = repo.addMileageIfWithinLimit(request.rollNo(), request.rollingKm(), now);
155	        if (!withinLimit) {
156	            RollRow current = repo.findRoll(request.rollNo());
157	            throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,
158	                    "本次实绩 " + request.rollingKm().stripTrailingZeros().toPlainString()
159	                            + " 公里将使轧辊 " + request.rollNo() + " 累计里程超过周期上限 "
160	                            + current.cycleLimitKm().stripTrailingZeros().toPlainString()
161	                            + " 公里（当前累计 " + current.totalKm().stripTrailingZeros().toPlainString()
162	                            + " 公里，剩余里程 " + remaining(current).stripTrailingZeros().toPlainString()
163	                            + " 公里），超限实绩不得入库");
164	        }
165	
166	        // 累计里程达到周期上限立即禁排。
167	        repo.banIfReachedLimit(request.rollNo(), now);
168	
169	        RollRow refreshed = repo.findRoll(request.rollNo());
170	        RollActualView view = new RollActualView(request.rollNo(), request.rollingKm(), true,
171	                false, firstUse, refreshed.totalKm(), remaining(refreshed), isBanned(refreshed),
172	                request.recordedAt());
173	        saveIdempotent(request.requestId(), BIZ_ACTUAL, fp, 200, FingerprintUtil.toJson(view));
174	        return view;
175	    }
176	
177	    // ---------------- 日冻结 ----------------
178	
179	    @Transactional
180	    public RollView freeze(String rollNo, RollFreezeRequest request) {
181	        String fp = FingerprintUtil.fingerprint(new FreezeFingerprint(request.requestId(), rollNo));
182	        Object replay = replayIfSame(request.requestId(), BIZ_FREEZE, fp);
183	        if (replay != null) {
184	            return (RollView) replay;
185	        }
186	
187	        RollRow roll = requireRoll(rollNo);
188	        if (roll.frozenAt() == null) {
189	            repo.markFrozen(rollNo, LocalDateTime.now(clock));
190	        }
191	        // 终态重复冻结：幂等成功，不重复写状态。
192	        RollView view = buildView(repo.findRoll(rollNo));
193	        saveIdempotent(request.requestId(), BIZ_FREEZE, fp, 200, FingerprintUtil.toJson(view));
194	        return view;
195	    }
196	
197	    // ---------------- 台账查询与复算 ----------------
198	
199	    @Transactional(readOnly = true)
200	    public RollView get(String rollNo) {
201	        return buildView(requireRoll(rollNo));
202	    }
203	
204	    /**
205	     * 台账复算：由实绩记录按时刻归位重算累计里程、本班卷数与首用标记，
206	     * 禁排状态按周期上限重判；复算后重复查询结果稳定。
207	     */
208	    @Transactional
209	    public RollView recompute(String rollNo) {
210	        RollRow roll = requireRoll(rollNo);
211	        List<RollActualRow> actuals = repo.findActualsByRoll(rollNo);
212	
213	        BigDecimal total = BigDecimal.ZERO;
214	        int coilsSinceMount = 0;
215	        for (RollActualRow actual : actuals) {
216	            total = total.add(actual.rollingKm());
217	            boolean inCampaign = !actual.recordedAt().isBefore(roll.mountedAt());
218	            boolean firstUse = inCampaign && coilsSinceMount < FIRST_USE_COILS;
219	            if (inCampaign) {
220	                coilsSinceMount++;
221	            }
222	            if (actual.firstUse() != firstUse) {
223	                repo.updateFirstUse(actual.id(), firstUse);
224	            }
225	        }
226	
227	        boolean banned = total.compareTo(roll.cycleLimitKm()) >= 0;
228	        repo.rewriteLedger(rollNo, total, coilsSinceMount, banned, LocalDateTime.now(clock));
229	        return buildView(repo.findRoll(rollNo));
230	    }
231	
232	    // ---------------- 内部方法 ----------------
233	
234	    private RollRow requireRoll(String rollNo) {
235	        RollRow roll = repo.findRoll(rollNo);
236	        if (roll == null) {
237	            throw new BusinessException(HttpStatus.NOT_FOUND, "轧辊不存在: " + rollNo);
238	        }
239	        return roll;
240	    }
241	
242	    /**
243	     * 构造“轧辊号＋时刻”重复回传的幂等视图并登记本次 requestId 的幂等记录。
244	     */
245	    private RollActualView dedupActualView(String requestId, String fp, RollActualRow existing) {
246	        RollRow roll = requireRoll(existing.rollNo());
247	        RollActualView view = new RollActualView(existing.rollNo(), existing.rollingKm(), false,
248	                false, existing.firstUse(), roll.totalKm(), remaining(roll), isBanned(roll),
249	                existing.recordedAt());
250	        saveIdempotent(requestId, BIZ_ACTUAL, fp, 200, FingerprintUtil.toJson(view));
251	        return view;
252	    }
253	
254	    private RollView buildView(RollRow roll) {
255	        return new RollView(roll.rollNo(), roll.status(), roll.totalKm(), roll.cycleLimitKm(),
256	                remaining(roll), roll.coilsSinceMount(), roll.mountedAt(), roll.frozenAt());
257	    }
258	
259	    private static BigDecimal remaining(RollRow roll) {
260	        return roll.cycleLimitKm().subtract(roll.totalKm());
261	    }
262	
263	    private static boolean isBanned(RollRow roll) {
264	        return STATUS_BANNED.equals(roll.status());
265	    }
266	
267	    /**
268	     * 同键重放：指纹一致返回首次响应；同键异参抛 409 且不产生任何写入。
269	     *
270	     * @return 首次响应对象；null 表示该 requestId 首次出现
271	     */
272	    private Object replayIfSame(String requestId, String bizType, String fingerprint) {
273	        IdempotentRow row = repo.findIdempotent(requestId);
274	        if (row == null) {
275	            return null;
276	        }
277	        if (!row.fingerprint().equals(fingerprint) || !row.bizType().equals(bizType)) {
278	            throw new ConflictException(HttpStatus.CONFLICT,
279	                    "requestId " + requestId + " 已用于不同业务参数的请求，拒绝执行且不产生任何写入");
280	        }
281	        return switch (bizType) {
282	            case BIZ_ACTUAL -> FingerprintUtil.fromJson(row.responseBody(), RollActualView.class);
283	            default -> FingerprintUtil.fromJson(row.responseBody(), RollView.class);
284	        };
285	    }
286	
287	    private void saveIdempotent(String requestId, String bizType, String fingerprint,
288	                                int httpStatus, String body) {
289	        boolean inserted = repo.tryInsertIdempotent(requestId, bizType, fingerprint, httpStatus,
290	                body, LocalDateTime.now(clock));
291	        if (!inserted) {
292	            // 并发同键首调竞争：唯一约束裁决后本事务所有写入将随异常回滚，
293	            // 客户端用相同 requestId 重放即可取得首次结果。
294	            throw new ConflictException(HttpStatus.CONFLICT,
295	                    "requestId " + requestId + " 正在被并发处理，唯一记录已存在，请用相同参数重放");
296	        }
297	    }
298	
299	    /** 冻结指纹载体：覆盖 requestId 与目标轧辊号。 */
300	    private record FreezeFingerprint(String requestId, String rollNo) {
301	    }
302	}
