1	package com.example.starter.rolling.repo;
2	
3	import org.springframework.dao.DuplicateKeyException;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.jdbc.core.RowMapper;
6	import org.springframework.stereotype.Repository;
7	
8	import java.math.BigDecimal;
9	import java.sql.Timestamp;
10	import java.time.LocalDateTime;
11	import java.util.List;
12	
13	/**
14	 * 轧辊寿命台账访问层：轧辊台账、换辊实绩、迟到事件，以及共享幂等记录表。
15	 */
16	@Repository
17	public class RollLifeRepository {
18	
19	    private final JdbcTemplate jdbc;
20	
21	    public RollLifeRepository(JdbcTemplate jdbc) {
22	        this.jdbc = jdbc;
23	    }
24	
25	    /** 轧辊台账行。status 为 IN_SERVICE/BANNED；totalKm 为累计实绩里程（公里）。 */
26	    public record RollRow(String rollNo, String status, BigDecimal totalKm, BigDecimal cycleLimitKm,
27	                          int coilsSinceMount, LocalDateTime mountedAt, LocalDateTime frozenAt,
28	                          LocalDateTime createdAt, LocalDateTime updatedAt) {
29	    }
30	
31	    /** 换辊实绩行。firstUse 为新辊上机后前 5 卷首用标记。 */
32	    public record RollActualRow(long id, String rollNo, BigDecimal rollingKm, boolean firstUse,
33	                                LocalDateTime recordedAt, String requestId, String fingerprint,
34	                                LocalDateTime createdAt) {
35	    }
36	
37	    /** 幂等记录行。 */
38	    public record IdempotentRow(String requestId, String bizType, String fingerprint,
39	                                int httpStatus, String responseBody, LocalDateTime createdAt) {
40	    }
41	
42	    private static final RowMapper<RollRow> ROLL_MAPPER = (rs, n) -> new RollRow(
43	            rs.getString("roll_no"), rs.getString("status"), rs.getBigDecimal("total_km"),
44	            rs.getBigDecimal("cycle_limit_km"), rs.getInt("coils_since_mount"),
45	            rs.getTimestamp("mounted_at").toLocalDateTime(),
46	            rs.getTimestamp("frozen_at") == null ? null : rs.getTimestamp("frozen_at").toLocalDateTime(),
47	            rs.getTimestamp("created_at").toLocalDateTime(),
48	            rs.getTimestamp("updated_at").toLocalDateTime());
49	
50	    private static final RowMapper<RollActualRow> ACTUAL_MAPPER = (rs, n) -> new RollActualRow(
51	            rs.getLong("id"), rs.getString("roll_no"), rs.getBigDecimal("rolling_km"),
52	            rs.getBoolean("first_use"), rs.getTimestamp("recorded_at").toLocalDateTime(),
53	            rs.getString("request_id"), rs.getString("fingerprint"),
54	            rs.getTimestamp("created_at").toLocalDateTime());
55	
56	    private static final RowMapper<IdempotentRow> IDEMPOTENT_MAPPER = (rs, n) -> new IdempotentRow(
57	            rs.getString("request_id"), rs.getString("biz_type"), rs.getString("fingerprint"),
58	            rs.getInt("http_status"), rs.getString("response_body"),
59	            rs.getTimestamp("created_at").toLocalDateTime());
60	
61	    // ---------------- 轧辊台账 ----------------
62	
63	    public void insertRoll(RollRow row) {
64	        jdbc.update("""
65	                INSERT INTO roll_life
66	                  (roll_no, status, total_km, cycle_limit_km, coils_since_mount,
67	                   mounted_at, frozen_at, created_at, updated_at)
68	                VALUES (?,?,?,?,?,?,?,?,?)
69	                """,
70	                row.rollNo(), row.status(), row.totalKm(), row.cycleLimitKm(), row.coilsSinceMount(),
71	                Timestamp.valueOf(row.mountedAt()),
72	                row.frozenAt() == null ? null : Timestamp.valueOf(row.frozenAt()),
73	                Timestamp.valueOf(row.createdAt()), Timestamp.valueOf(row.updatedAt()));
74	    }
75	
76	    public RollRow findRoll(String rollNo) {
77	        List<RollRow> rows = jdbc.query(
78	                "SELECT * FROM roll_life WHERE roll_no = ?", ROLL_MAPPER, rollNo);
79	        return rows.isEmpty() ? null : rows.get(0);
80	    }
81	
82	    /**
83	     * 重新上机：重置本班卷数并恢复在役状态，累计里程与周期上限保持台账原值。
84	     */
85	    public void remount(String rollNo, LocalDateTime mountedAt, LocalDateTime now) {
86	        jdbc.update("""
87	                UPDATE roll_life
88	                SET status = 'IN_SERVICE', coils_since_mount = 0, mounted_at = ?, updated_at = ?
89	                WHERE roll_no = ?
90	                """, Timestamp.valueOf(mountedAt), Timestamp.valueOf(now), rollNo);
91	    }
92	
93	    /**
94	     * 原子累计里程：仅当累计后不超周期上限时生效，数据库裁决并发回报。
95	     *
96	     * @return true 累计成功；false 表示超限，本次实绩不得入库（事务回滚）
97	     */
98	    public boolean addMileageIfWithinLimit(String rollNo, BigDecimal km, LocalDateTime now) {
99	        int affected = jdbc.update("""
100	                UPDATE roll_life
101	                SET total_km = total_km + ?, coils_since_mount = coils_since_mount + 1, updated_at = ?
102	                WHERE roll_no = ? AND total_km + ? <= cycle_limit_km
103	                """, km, Timestamp.valueOf(now), rollNo, km);
104	        return affected == 1;
105	    }
106	
107	    /**
108	     * 累计里程达到周期上限即禁排（恰达上限也禁排）。
109	     */
110	    public void banIfReachedLimit(String rollNo, LocalDateTime now) {
111	        jdbc.update("""
112	                UPDATE roll_life SET status = 'BANNED', updated_at = ?
113	                WHERE roll_no = ? AND total_km >= cycle_limit_km AND status <> 'BANNED'
114	                """, Timestamp.valueOf(now), rollNo);
115	    }
116	
117	    public void markFrozen(String rollNo, LocalDateTime now) {
118	        jdbc.update("""
119	                UPDATE roll_life SET frozen_at = ?, updated_at = ? WHERE roll_no = ?
120	                """, Timestamp.valueOf(now), Timestamp.valueOf(now), rollNo);
121	    }
122	
123	    /**
124	     * 复算回写台账：total_km/coils_since_mount 由实绩记录重算，禁排状态按上限重判。
125	     */
126	    public void rewriteLedger(String rollNo, BigDecimal totalKm, int coilsSinceMount,
127	                              boolean banned, LocalDateTime now) {
128	        jdbc.update("""
129	                UPDATE roll_life
130	                SET total_km = ?, coils_since_mount = ?, status = ?, updated_at = ?
131	                WHERE roll_no = ?
132	                """, totalKm, coilsSinceMount, banned ? "BANNED" : "IN_SERVICE",
133	                Timestamp.valueOf(now), rollNo);
134	    }
135	
136	    // ---------------- 换辊实绩 ----------------
137	
138	    public void insertActual(RollActualRow row) {
139	        jdbc.update("""
140	                INSERT INTO roll_change_actual
141	                  (id, roll_no, rolling_km, first_use, recorded_at, request_id, fingerprint, created_at)
142	                VALUES (?,?,?,?,?,?,?,?)
143	                """,
144	                row.id(), row.rollNo(), row.rollingKm(), row.firstUse(),
