96	    @Test
97	    void 超限实绩拒绝入库且里程不变() {
98	        mount("R-OVER", "10");
99	        rollService.reportActual(actual("ov-1", "R-OVER", "6", 1));
100	
101	        assertThatThrownBy(() -> rollService.reportActual(actual("ov-2", "R-OVER", "5", 2)))
102	                .isInstanceOf(BusinessException.class)
103	                .hasMessageContaining("超过周期上限")
104	                .hasMessageContaining("剩余里程 4");
105	
106	        assertThat(jdbc.queryForObject(
107	                "SELECT COUNT(1) FROM roll_change_actual WHERE roll_no = 'R-OVER'",
108	                Integer.class)).isEqualTo(1);
109	        RollView roll = rollService.get("R-OVER");
110	        assertThat(roll.totalKm()).isEqualByComparingTo("6");
111	        assertThat(roll.status()).isEqualTo("IN_SERVICE");
112	    }
113	
114	    @Test
