297	    // ---------------- 并发辅助 ----------------
298	
299	    private record Outcome(RollActualView view, boolean conflict, String error) {
300	    }
301	
302	    private interface ActualTask {
303	        RollActualRequest request(int index);
304	    }
305	
306	    private List<Outcome> runConcurrent(int n, ActualTask task) throws Exception {
307	        CountDownLatch ready = new CountDownLatch(n);
308	        CountDownLatch start = new CountDownLatch(1);
309	        ExecutorService pool = Executors.newFixedThreadPool(n);
310	        try {
311	            List<Future<Outcome>> futures = new ArrayList<>();
312	            for (int i = 0; i < n; i++) {
313	                int index = i;
314	                futures.add(pool.submit(() -> {
315	                    ready.countDown();
316	                    assertThat(start.await(30, TimeUnit.SECONDS)).isTrue();
317	                    try {
318	                        return new Outcome(rollService.reportActual(task.request(index)),
319	                                false, null);
320	                    } catch (ConflictException e) {
321	                        return new Outcome(null, true, e.getMessage());
322	                    } catch (Exception e) {
323	                        return new Outcome(null, false,
324	                                e.getClass().getSimpleName() + ": " + e.getMessage());
325	                    }
326	                }));
327	            }
328	            assertThat(ready.await(30, TimeUnit.SECONDS)).isTrue();
329	            start.countDown();
330	
331	            List<Outcome> outcomes = new ArrayList<>();
332	            for (Future<Outcome> f : futures) {
333	                outcomes.add(f.get(30, TimeUnit.SECONDS));
334	            }
335	            return outcomes;
336	        } finally {
337	            pool.shutdownNow();
338	            assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
339	        }
340	    }
341	}
