        Integer count = jdbc.queryForObject("""
                SELECT COUNT(1) FROM roll_repair_inspection
                WHERE request_id_pk = ? AND approved = 1
                """, Integer.class, requestIdPk);
        return count == null ? 0 : count;
    }
}

